import java.util.Arrays;
import java.util.Scanner;
​
public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
​
    int n = Integer.parseInt(sc.nextLine());
    int[] a = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    int[] b = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
​
    int result = handle(n, a, b);
    System.out.println(result);
  }
​
  public static int handle(int n, int[] a, int[] b) {
    Arrays.sort(a);
    Arrays.sort(b);
​
    int la = 0; // 指向a的最小值index
    int ra = n - 1; // 指向a的最大值index
​
    int lb = 0; // 指向b的最小值index
    int rb = n - 1; // 指向b的最大值index
​
    int ans = 0; // 记录a可以获得的分数
​
    while (la <= ra) {
      if (a[ra] > b[rb]) {
        //  a最大值 > b的最大值 直接比
        ans += 1;
        ra--;
        rb--;
      } else if (a[ra] < b[rb]) {
        // a最大值 < b的最大值, 损失掉a的最小值，保留最大值
        ans -= 1;
        la++;
        rb--;
      } else {
        // 相等情况下 ，a最小值大于b最小值，先考虑左指针移动
        if (a[la] > b[lb]) {    
          ans += 1;
          la++;
          lb++;
        // 相等情况下，a的最小值小于b的最小值。 使用a的最小值和b的最大值对抗  
        } else {
          // a [1 1 1] b[1 1 1] 考虑这个情况    
          if (b[rb] > a[la]) ans -= 1;
          la++;
          rb--;
        }
      }
    }
​
    return ans;
  }
}

