function handle(n, a, b) {
  a.sort((a, b) => a - b);
  b.sort((a, b) => a - b);
​
  let la = 0; // 指向a的最小值index
  let ra = n - 1; // 指向a的最大值index
​
  let lb = 0; // 指向b的最小值index
  let rb = n - 1; // 指向b的最大值index
​
  let ans = 0; // 记录a可以获得的分数
​
  while (la <= ra) {
    if (a[ra] > b[rb]) {
      // a最大值 > b的最大值 直接比
      ans += 1;
      ra--;
      rb--;
    } else if (a[ra] < b[rb]) {
      // 最小消耗最大
      ans -= 1;
      la++;
      rb--;
    } else {
     // 相等情况下 ，a最小值大于b最小值，先考虑左指针移动  
      if (a[la] > b[lb]) {     
        ans += 1;
        la++;
        lb++;
      // 相等情况下，a的最小值小于b的最小值。 使用a的最小值和b的最大值对抗
      } else {
        //  a [1 1 1] b[1 1 1] 考虑这个情况
        if (b[rb] > a[la]) ans -= 1;
        la++;
        rb--;
      }
    }
  }
​
  return ans;
}

