package main
​
import (
    "fmt"
    "sort"
)
​
func main() {
    var n int
    fmt.Scan(&n)
​
    aScores := make([]int, n)
    bScores := make([]int, n)
​
    for i := 0; i < n; i++ {
        fmt.Scan(&aScores[i])
    }
    for i := 0; i < n; i++ {
        fmt.Scan(&bScores[i])
    }

    sort.Ints(aScores)
    sort.Ints(bScores)
    // 双指针分别最大值和最小值下
    leftA, rightA := 0, n-1
    leftB, rightB := 0, n-1
    res := 0
​
    for leftB <= rightB {
        // a最大值 > b最大值 直接比
        if aScores[rightA] > bScores[rightB] {
            rightA--
            rightB--
            res++
          // 肯定会输，选择最小值来输   
        } else if aScores[rightA] < bScores[rightB] {
            rightB--
            leftA++
            res--
        } else {
            // 相等情况下 ，a最小值大于b最小值，先考虑左指针移动
            if aScores[leftA] > bScores[leftB] {
                res++
                leftA++
                leftB++
            // 相等情况下，a的最小值小于b的最小值。 使用a的最小值和b的最大值对抗   
            } else {
                //  a [1 1 1] b[1 1 1] 考虑这个情况 最小值和最大值相等情况了
                if bScores[rightB] > aScores[leftA] {
                    res--
                }
                leftA++
                rightB--
            }
        }
    }
​
    fmt.Println(res)
}
